    "CARGA_DOCENTE_ID" bigint NOT NULL,
    "NUMERO_UNIDAD" character varying(30) NOT NULL,
    "NOMBRE" character varying(180) NOT NULL,
    "SEMANA_INICIO" integer,
    "FECHA_INICIO" date NOT NULL,
    "FECHA_TERMINO" date NOT NULL,
    "SEMANAS_ESTIMADAS" integer DEFAULT 1 NOT NULL,
    "CLASES_PLANIFICADAS" integer DEFAULT 0 NOT NULL,
    "DESCRIPCION_GENERAL" text,
    "OBJETIVOS_APRENDIZAJE" text,
    "INDICADORES_LOGRO" text,
    "ESTADO" character varying(20) NOT NULL,
    "CREADO_POR_USUARIO_ID" bigint NOT NULL,
    "FECHA_CREACION" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "FECHA_ACTUALIZACION" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_CLASES" CHECK (("CLASES_PLANIFICADAS" >= 0)),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_ESTADO" CHECK ((("ESTADO")::text = ANY ((ARRAY['BORRADOR'::character varying, 'CREADA'::character varying, 'ACTIVA'::character varying, 'COMPLETADA'::character varying])::text[]))),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_FECHAS" CHECK (("FECHA_TERMINO" >= "FECHA_INICIO")),
    CONSTRAINT "CHK_UNIDADES_PLANIFICACION_SEMANAS" CHECK (("SEMANAS_ESTIMADAS" >= 1))
);


