-- Name: curriculum_objective_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.curriculum_objective_items (
    id integer NOT NULL,
    objective_id uuid NOT NULL,
    orden integer NOT NULL,
    descripcion text NOT NULL
);


--
-- Name: curriculum_objective_items_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.curriculum_objective_items_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: curriculum_objective_items_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.curriculum_objective_items_id_seq OWNED BY public.curriculum_objective_items.id;


--
-- Name: curriculum_objectives; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.curriculum_objectives (
    id uuid NOT NULL,
    grade_id uuid NOT NULL,
    codigo character varying(20) NOT NULL,
    tipo character varying(20) NOT NULL,
    eje character varying(200),
    descripcion text NOT NULL
);


--
-- Name: curriculum_subjects; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.curriculum_subjects (
    id uuid NOT NULL,
    slug character varying(100) NOT NULL,
    nombre character varying(200) NOT NULL,
    total_grados integer NOT NULL,
    created_at timestamp without time zone DEFAULT now()
);


