-- Name: planning_class_curriculum_objectives; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.planning_class_curriculum_objectives (
    planning_class_id bigint NOT NULL,
    objective_id uuid NOT NULL
);


